//! 🧪️ Real UI leaf receivers conserve original source custody through refusal, cancellation and paid retirement.
use crate::*;
use semio_framework_value::{DslValue,NativeDecodeControl,RetainedCloneGrant,RetainedCloneProgress,RetirementDemand,ValueError,native_decoding::{NativeReceive,NativeReceiver,NativeDecodeConstructionRecipient,NativeDecodeWorkRecipient},retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
struct Construction(RetainedCloneGrant,RetainedCloneProgress);
impl NativeDecodeConstructionRecipient for Construction{fn submitted(&self)->RetainedCloneProgress{self.1}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(self.0,d));Ok(self.0)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.1=self.1.checked_add(p)?;assert!(p.fits(g)&&p.fits(self.0));Ok(())}}
struct Work<'a>(&'a u64);
impl NativeDecodeWorkRecipient for Work<'_>{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{let limit:u64=(*self.0).min(1);limit.checked_sub(observed).ok_or_else(||ValueError::invariant("native observed work exceeds its actual finite scope"))}fn admits(&mut self,seen:u64,next:u64)->Result<bool,ValueError>{Ok(seen.checked_add(next).is_some_and(|n|n<=(*self.0).min(1)))}}
pub(crate) fn run<T:NativeReceive<DslValue>+serde::Serialize+serde::de::DeserializeOwned>(row:&serde_json::Value,cut:Option<usize>,profile:&serde_json::Value){
 let wire=row["wire"].as_str().unwrap();let accepted=row["accepted"].as_bool().unwrap();let oracle=serde_json::from_str::<T>(wire);assert_eq!(oracle.is_ok(),accepted);let expected:serde_json::Value=serde_json::from_str(wire).unwrap();if let Ok(value)=oracle{assert_eq!(serde_json::to_value(value).unwrap(),expected);}
 let s=&profile["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();
 let(mut source,_,_)=semio_framework_value::testing::admit_owned_source(DslValue::from(expected.clone()),());let identity=std::ptr::from_ref(source.borrow().get());let mut receiver=T::receiver();let mut allow=|_|true;let mut control=NativeDecodeControl::new_retained(&mut allow);let mut output=None;let mut refused=false;
 let post=|p:RetainedCloneProgress,work:u64,heap:(usize,usize),bank:&mut RetainedCloneGrant,fuel:&mut u64|{assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).expect("UI leaf exhausted declared CPU stock");};
 for at in 0..100000{if cut==Some(at){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let denied=RetainedCloneGrant{maximum_items:0,..g};let(turn,heap)=observe(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));
  let mut construction=Construction(g,Default::default());let mut work=Work(&fuel);let mut actual_work=0;let(result,heap)=observe(||control.with_work_recipient(&mut work,|control|control.with_construction_recipient(&mut construction,|control|{let turn=receiver.advance(source.borrow(),control,4096,g);actual_work=turn.work;turn.result})));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());post(p,actual_work,heap,&mut bank,&mut fuel);if let Err(ref error)=result{assert!(!accepted,"family {} wire {} receiver error {:?}",row["family"],wire,error);refused=true;break}assert_eq!(std::ptr::from_ref(source.borrow().get()),identity);if receiver.output_ready(){let(turn,heap)=observe(||receiver.take(g));let(value,p)=turn.result.unwrap().expect("funded leaf handoff");post(p,turn.work,heap,&mut bank,&mut fuel);assert_eq!(serde_json::to_value(&value).unwrap(),expected);output=Some(value);break}}
 if cut.is_none(){assert_eq!(refused,!accepted);assert_eq!(output.is_some(),accepted);}receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(turn,heap)=observe(||receiver.close_step(g));post(turn.result.unwrap().progress(),turn.work,heap,&mut bank,&mut fuel);}assert!(receiver.terminal_is_empty());
 if let Some(value)=output{let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("UI leaf owns controlled retirement"));for _ in 0..100000{if close.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(result,heap)=observe(||close.step(g));let work=close.last_turn_work();post(result.unwrap().progress(),work,heap,&mut bank,&mut fuel);}assert!(close.terminal_is_empty());}
 for _ in 0..100000{if source.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(turn,heap)=observe(||source.close_step(g));post(turn.result.unwrap().progress(),turn.work,heap,&mut bank,&mut fuel);}assert!(source.terminal_is_empty());assert!(fuel>0);
}
#[test]
fn native_ui_leaves_match_actual_serde_and_close_every_original_frontier(){let c:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in c["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(c["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){match row["family"].as_str().unwrap(){"Variant"=>run::<Variant>(row,cut,&c),"SizeToken"=>run::<SizeToken>(row,cut,&c),"Density"=>run::<Density>(row,cut,&c),"Tone"=>run::<Tone>(row,cut,&c),"Emphasis"=>run::<Emphasis>(row,cut,&c),"Liveness"=>run::<Liveness>(row,cut,&c),"UiNodeId"=>run::<UiNodeId>(row,cut,&c),"UiRevision"=>run::<UiRevision>(row,cut,&c),"SurfaceId"=>run::<SurfaceId>(row,cut,&c),"SurfaceProps"=>run::<SurfaceProps>(row,cut,&c),"Activity"=>run::<Activity>(row,cut,&c),"SpaceToken"=>run::<SpaceToken>(row,cut,&c),"Axis"=>run::<Axis>(row,cut,&c),"Align"=>run::<Align>(row,cut,&c),"Justify"=>run::<Justify>(row,cut,&c),"ScrollAxes"=>run::<ScrollAxes>(row,cut,&c),"Anchor"=>run::<Anchor>(row,cut,&c),"TransitionHint"=>run::<TransitionHint>(row,cut,&c),"StyleSpec"=>run::<StyleSpec>(row,cut,&c),"AccessibilitySpec"=>run::<AccessibilitySpec>(row,cut,&c),"Label"=>run::<Label>(row,cut,&c),"ActionId"=>run::<ActionId>(row,cut,&c),"Trigger"=>run::<Trigger>(row,cut,&c),"ActionBinding"=>run::<ActionBinding>(row,cut,&c),"MenuRef"=>run::<MenuRef>(row,cut,&c),"UiIntent"=>run::<UiIntent>(row,cut,&c),"UiPublicationRevision"=>run::<UiPublicationRevision>(row,cut,&c),"WindowLayout"=>run::<WindowLayout>(row,cut,&c),_=>panic!("declared UI leaf family")}}}}
